from pathlib import Path
import re, collections
s=Path('candidate/statement-ledger.md').read_text(); rows=[]
for n,l in enumerate(s.splitlines(),1):
 if n>708 and l.startswith('|'):
  a=re.findall(r'"'`((?:StratonovichHAMSecondMoment|StratonovichHAMAudit)'"\\.["'^`]+)`'"', l.split('|')[2] if len(l.split('|'))>2 else '')
  rows += [(n,x,l.split('|')[1].strip()) for x in a]
c=Path('lean/claims.yaml').read_text(); ds=re.findall(r'"'^  decl: (.+)$'"',c,re.M); ids=re.findall(r'"'^- id: (.+)$'"',c,re.M)
rc=collections.Counter(x for _,x,_ in rows)
print('per-module ledger rows:',len(rows),'unique:',len(rc)); print('claims',len(ds),'kinds',collections.Counter(re.findall(r'"'^  kind: (.+)$'"',c,re.M)));print('missing',set(ds)-rc.keys());print('duplicate',[(x,n) for x,n in rc.items() if n"'!=1]);print('"'label split',collections.Counter('no direct label' if y.startswith('no direct label') else 'label' for _,_,y in rows))
for d in ds:
 if '.L8Completed.' in d:
  short=d.split('.',1)[1]; matches=[(n,l.split('|')[1].strip()) for n,l in enumerate(s.splitlines(),1) if 365<=n<=704 and '"'`'"'+short+'"'`'"' in l]; print(short,matches)
cv=Path('lean/coverage.yaml').read_text(); cs=set(ids); missing=set(re.findall(r'"'^  - (stratonovich-ham-second-moment-lean/[''^'"\\s]+)"'$'"',cv,re.M))-cs; print('coverage ids missing',missing)
blocks=re.split(r'(?m)"'^- paper:'"',cv)[1:]; cc=collections.Counter(); outside=[]
for b in blocks:
 cl=re.search(r'(?m)"'^  class: (.+)$'"',b).group(1);co=re.search(r'(?m)"'^  conclusion: (.+)$'"',b);cc[cl]+=1;cc[(cl,co.group(1) if co else 'full')]+=1
 if cl=='outside':outside.append(re.search(r'label: (.+)',b).group(1))
print('coverage classes:',dict(cc),'outside:',outside)
labels=collections.defaultdict(list)
for p in Path('manuscript').rglob('*'):
 if p.is_file():
  for n,l in enumerate(p.read_text().splitlines(),1):
   for t in re.findall(r'\\\\label\\{(["'^}]+)'"\\}',l):labels[t].append(f'{p}:{n}')
wanted=set(re.findall(r'"'`([CEHLPST]:[''^`]+)`'"', '\\n'.join(s.splitlines()[2726:2813])))
print('L8 cited label occurrences:',{t:labels[t] for t in sorted(wanted)})
print('library modules',len(list(Path('lean/StratonovichHAMSecondMoment').glob('*.lean'))))
PY"

